assert len(IDEAS) == 100, len(IDEAS)

def score(v, t, f, p):
    return round(v*0.30 + t*0.30 + f*0.20 + p*0.20, 1)

items = []
for i, it in enumerate(IDEAS, 1):
    title, genre, pitch, loop, vis, feas, rep, v, t, f, p = it
    items.append({
        "id": i, "название": title, "жанр_и_камера": genre, "описание": pitch,
        "геймплей_и_управление": loop, "визуал_и_шейдеры": vis,
        "выполнимость_на_ПК": feas, "реиграбельность": rep,
        "оценка": {"визуал_30": v, "техника_30": t, "фан_20": f, "физика_20": p, "итог": score(v, t, f, p)},
    })

here = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(here, "100_3D_GAME_IDEAS.json"), "w", encoding="utf-8") as fh:
    json.dump({"стандарт_визуала": "How to Fish", "пресет": "А — Стилизованная вода и физика природы", "идеи": items}, fh, ensure_ascii=False, indent=2)

ranked = sorted(items, key=lambda x: -x["оценка"]["итог"])
with open(os.path.join(here, "100_3D_GAME_IDEAS.md"), "w", encoding="utf-8") as fh:
    fh.write("# Каталог 100 реалистичных 3D-идей игр (стандарт «How to Fish»)\n\n")
    fh.write("Пресет графики: **А — Стилизованная вода и физика природы**.\n\n")
    fh.write("## Скоринговая матрица (ТОП-10)\n\n| Место | ID | Название | Визуал 30% | Техника 30% | Фан 20% | Физика 20% | Итог |\n|---|---|---|---|---|---|---|---|\n")
    for n, it in enumerate(ranked[:10], 1):
        o = it["оценка"]
        fh.write(f"| {n} | {it['id']} | {it['название']} | {o['визуал_30']} | {o['техника_30']} | {o['фан_20']} | {o['физика_20']} | **{o['итог']}** |\n")
    fh.write(f"\n**Победитель: #{ranked[0]['id']} «{ranked[0]['название']}» — {ranked[0]['оценка']['итог']} / 100.**\n\n## Полный каталог\n\n")
    for it in items:
        fh.write(f"### {it['id']}. {it['название']}\n")
        fh.write(f"- **Жанр и камера:** {it['жанр_и_камера']}\n- **Концепция:** {it['описание']}\n")
        fh.write(f"- **Геймплейный цикл и управление:** {it['геймплей_и_управление']}\n- **Визуальный стиль и шейдеры:** {it['визуал_и_шейдеры']}\n")
        fh.write(f"- **Выполнимость на ПК:** {it['выполнимость_на_ПК']}/10 · **Реиграбельность:** {it['реиграбельность']}/10 · **Итоговый балл:** {it['оценка']['итог']}/100\n\n")
print("TOP:", [(r["id"], r["название"], r["оценка"]["итог"]) for r in ranked[:5]])
